        void PlayerBuildLab()
        {
            Heading("PLAYER BUILD SNAPSHOT","Generated and manual snapshots evaluate without entering Play Mode.");BuildInputs();ObjectiveInputs();ConstraintInputs();using(new EditorGUILayout.HorizontalScope()){if(GUILayout.Button("EVALUATE BUILD",GUILayout.Height(30)))Run("Player build evaluation",_=>{playerMetrics=PlayerBuildEvaluator.Evaluate(playerBuild);contributions=PlayerBuildContributionAnalyzer.Analyze(playerBuild,objective);});if(GUILayout.Button("CLEAR GEAR")){playerBuild.equipment.Clear();playerMetrics=null;}if(GUILayout.Button("CLEAR PASSIVES")){playerBuild.passiveStableIds.Clear();playerMetrics=null;}if(GUILayout.Button("EXPORT JSON"))status=WorkbenchExports.SaveJson("player_build",playerBuild);if(playerMetrics!=null&&GUILayout.Button("EXPORT CSV"))status=WorkbenchExports.SaveBuildCsv(playerBuild,playerMetrics);}
            Heading("MANUAL / GENERATED EQUIPMENT");gearProfile=(PlayerGearProfileSO)EditorGUILayout.ObjectField("Generation Profile",gearProfile,typeof(PlayerGearProfileSO),false);if(gearProfile==null)gearProfile=AssetDatabase.LoadAssetAtPath<PlayerGearProfileSO>("Assets/Balance/Profiles/SO_PlayerGearProfile_Mid.asset");if(GUILayout.Button("GENERATE COMPLETE GEARSET"))Run("Gear optimization",_=>{gearResult=PlayerGearsetOptimizer.Optimize(playerBuild,gearProfile,objective,gearProfile.selectionStrategy==PlayerGearSelectionStrategy.FullGearsetBeamSearch,playerConstraints,Progress("Gear search"),()=>cancelled);playerBuild=gearResult.build;playerMetrics=gearResult.metrics;contributions=PlayerBuildContributionAnalyzer.Analyze(playerBuild,objective);});foreach(var g in playerBuild.equipment.OrderBy(x=>x.slot))using(new EditorGUILayout.HorizontalScope(EditorStyles.helpBox)){GUILayout.Label(g.Description,GUILayout.MinWidth(400));bool locked=playerConstraints.lockedSlots.Contains(g.slot);if(GUILayout.Button(locked?"Unlock":"Lock",GUILayout.Width(55))){if(locked)playerConstraints.lockedSlots.Remove(g.slot);else playerConstraints.lockedSlots.Add(g.slot);}if(GUILayout.Button("Clear",GUILayout.Width(55))){playerBuild.equipment.Remove(g);break;}if(GUILayout.Button("Inspect",GUILayout.Width(60)))EditorUtility.DisplayDialog(g.slot.ToString(),g.Description,"Close");}
            if(playerMetrics!=null){MetricsPanel(playerMetrics);Heading("BUILD A vs BUILD B");using(new EditorGUILayout.HorizontalScope()){if(GUILayout.Button("Capture as A"))compareA=playerMetrics;if(GUILayout.Button("Capture as B"))compareB=playerMetrics;}if(compareA!=null&&compareB!=null)Compare(compareA,compareB);}
            Heading("SEND THIS BUILD TO ANALYSIS");using(new EditorGUILayout.HorizontalScope()){if(GUILayout.Button("SENSITIVITY")){sensitivity.build=playerBuild.Clone();tab=Tab.Sensitivity;}if(GUILayout.Button("AFFIX ANALYZER")){affixRequest.build=playerBuild.Clone();tab=Tab.AffixAnalyzer;}if(GUILayout.Button("LOOT PROGRESSION")){lootRequest.build=playerBuild.Clone();tab=Tab.LootProgression;}if(GUILayout.Button("BREAKPOINT FINDER"))tab=Tab.BreakpointFinder;if(GUILayout.Button("COMBAT LAB")){combatRequest.player=playerBuild;tab=Tab.CombatLab;}}
        }
        void MetricsPanel(PlayerBuildMetrics m)
        {
            Heading("AUTHORITATIVE ANALYTICAL METRICS");EditorGUILayout.LabelField("Average hit / Basic DPS",$"{m.averageHit:0.##} / {m.basicDps:0.##}");EditorGUILayout.LabelField("APS / Crit / Crit Multi",$"{m.attacksPerSecond:0.###} / {m.critChance:P2} / {m.critMultiplier:0.###}x");EditorGUILayout.LabelField("Physical · Fire · Cold · Lightning · Void",$"{m.physicalOutput:0.#} · {m.fireOutput:0.#} · {m.coldOutput:0.#} · {m.lightningOutput:0.#} · {m.voidOutput:0.#}");EditorGUILayout.LabelField("Poison · Bleed · Ignite DPS",$"{m.poisonDps:0.#} · {m.bleedDps:0.#} · {m.igniteDps:0.#}");EditorGUILayout.LabelField("Life / Armour / Mana",$"{m.life:0.#} / {m.armour:0.#} / {m.mana:0.#}");EditorGUILayout.LabelField("EHP Phys · Fire · Cold · Lightning · Void",$"{m.ehpPhysical:0.#} · {m.ehpFire:0.#} · {m.ehpCold:0.#} · {m.ehpLightning:0.#} · {m.ehpVoid:0.#}");foreach(var skill in m.skills)EditorGUILayout.LabelField(skill.name,$"{skill.averageDamagePerUse:0.#}/use · {skill.effectiveCooldown:0.##}s · {(skill.sustainable?"sustainable":"Mana pressure")}");foreach(string assumption in m.assumptions)EditorGUILayout.HelpBox(assumption,MessageType.None);
            Heading("DAMAGE CONTRIBUTION TRACE");EditorGUILayout.LabelField("Base weapon average",m.baseWeaponAverage.ToString("0.###"));EditorGUILayout.LabelField("Attribute / level increased",$"{m.weaponAttributeIncreased:P2} / {m.playerLevelIncreased:P2}");EditorGUILayout.LabelField("Generic / Physical increased",$"{m.genericIncreased:P2} / {m.physicalIncreased:P2}");EditorGUILayout.LabelField("Generic / Physical more",$"{m.genericMore:P2} / {m.physicalMore:P2}");EditorGUILayout.LabelField("Crit / Hit Twice expectation",$"{m.critContribution:0.###} / {m.hitTwiceContribution:0.###}");
            if(contributions.Count>0){Heading("MARGINAL / ABLATION CONTRIBUTION");foreach(var x in contributions)EditorGUILayout.LabelField(x.source,$"Primary {x.primary:+0.###;-0.###;0} · Secondary {x.secondary:+0.###;-0.###;0}");EditorGUILayout.HelpBox("Interacting source categories do not necessarily sum to the full metric.",MessageType.None);}
            if(gearResult!=null){Heading("SCENARIO-RELATIVE ITEM CONTRIBUTIONS");foreach(var x in gearResult.selected)EditorGUILayout.LabelField(x.item.slot.ToString(),$"Objective {x.score:+0.####;-0.####;0} · Primary {x.primaryDelta:+0.##;-0.##;0} · Secondary {x.secondaryDelta:+0.##;-0.##;0}");EditorGUILayout.LabelField("Gear search debug",$"Generated {gearResult.debug.generated}; retained {gearResult.debug.retained}; states {gearResult.debug.statesEvaluated}; pruned {gearResult.debug.statesPruned}; beam {gearResult.debug.beamWidth}");if(GUILayout.Button("EVALUATE FINAL GEARSET WITH COMBAT LAB")){playerBuild=gearResult.build.Clone();combatRequest.player=playerBuild;tab=Tab.CombatLab;}}
        }
