            heatZoom=EditorGUILayout.Slider("Zoom",heatZoom,.03f,.18f);Rect r=GUILayoutUtility.GetRect(700,700,GUILayout.ExpandWidth(true));EditorGUI.DrawRect(r,new Color(.035f,.04f,.055f));DrawTreeHeatmap(r);
            if(selectedMarginal!=null){EditorGUILayout.HelpBox($"{selectedMarginal.name}\n{selectedMarginal.effect}\nLegal now: {selectedMarginal.immediatelyLegal}\nPrimary {selectedMarginal.primaryDelta:+0.###;-0.###;0}; Secondary {selectedMarginal.secondaryDelta:+0.###;-0.###;0}; Objective {selectedMarginal.objectiveDelta:+0.#####;-0.#####;0}; Path cost {selectedMarginal.pathCost}; Path-adjusted {selectedMarginal.pathAdjustedValue:+0.#####;-0.#####;0}",MessageType.None);using(new EditorGUILayout.HorizontalScope()){if(GUILayout.Button("SELECT OWNING BRANCH SO"))PingNode(selectedMarginal.nodeId);if(GUILayout.Button("WHY THIS NODE?"))EditorUtility.DisplayDialog("Why this node?",$"Immediate Primary: {selectedMarginal.primaryDelta:+0.###;-0.###;0}\nImmediate Secondary: {selectedMarginal.secondaryDelta:+0.###;-0.###;0}\nObjective: {selectedMarginal.objectiveDelta:+0.#####;-0.#####;0}\nMinimum legal package: {selectedMarginal.pathCost} point(s)\nPath-adjusted value: {selectedMarginal.pathAdjustedValue:+0.#####;-0.#####;0}","Close");}}
            EditorGUILayout.LabelField("Legend","Blue: no measured value · Yellow: moderate · Red: strongest value · White: optimizer-selected path");
        }
        void ScenarioSweep()
        {
            Heading("END-TO-END PLAYER SCENARIO SWEEP");BuildInputs();ObjectiveInputs();SweepInputs(100);MetricPopup();scenarioPassives=EditorGUILayout.Toggle("Optimize Passives",scenarioPassives);scenarioProgressive=EditorGUILayout.Toggle("Progressive Character",scenarioProgressive);if(scenarioProgressive)scenarioFreeRespec=EditorGUILayout.Toggle("Allow Free Respec",scenarioFreeRespec);passiveBeamWidth=EditorGUILayout.IntSlider("Passive Beam Width",passiveBeamWidth,1,500);if(GUILayout.Button("RUN PROFILE COMPARISON",GUILayout.Height(30)))Run("Scenario sweep",_=>{playerSweep=PlayerScenarioSweep.Run(playerBuild,LoadProfiles(),objective,sweepStart,sweepEnd,sweepIncrement,scenarioPassives,scenarioProgressive,scenarioFreeRespec,passiveBeamWidth,Progress("Scenario"),()=>cancelled);curves=playerSweep.Curves(curveMetric);});DrawPlayerCurves();
        }
        void PlayerVsEnemy()
        {
            Heading("PLAYER vs ENEMY — NEUTRAL ANALYTICAL RATIOS");EditorGUILayout.HelpBox("TTK and TTD are neutral analytical estimates, not simulated encounter duration. Combat Lab will own real fight sequencing.",MessageType.Info);if(playerMetrics==null)playerMetrics=PlayerBuildEvaluator.Evaluate(playerBuild);if(enemyResult==null){EditorGUILayout.HelpBox("Run Enemy Gear Lab first; the comparison reuses that exact generated dataset.",MessageType.Warning);return;}var enemies=enemyResult.samples.OrderBy(x=>x.gearScore).ToList();EnemySample p50=enemies[Mathf.Clamp((int)Math.Round((enemies.Count-1)*.5),0,enemies.Count-1)],p90=enemies[Mathf.Clamp((int)Math.Round((enemies.Count-1)*.9),0,enemies.Count-1)];EditorGUILayout.LabelField("P50 expected TTK",PlayerScenarioSweep.AnalyticalTtk(playerMetrics,p50).ToString("0.###")+" s-equivalent");EditorGUILayout.LabelField("P90 expected TTK",PlayerScenarioSweep.AnalyticalTtk(playerMetrics,p90).ToString("0.###")+" s-equivalent");EditorGUILayout.LabelField("P50 expected TTD",PlayerScenarioSweep.AnalyticalTtd(playerMetrics,p50).ToString("0.###")+" s-equivalent");EditorGUILayout.LabelField("P90 expected TTD",PlayerScenarioSweep.AnalyticalTtd(playerMetrics,p90).ToString("0.###")+" s-equivalent");if(playerSweep!=null){Heading("NORMALIZED CURVE MODE (FIRST POINT = 100)");var normalized=playerSweep.Curves(curveMetric);foreach(var series in normalized){double baseValue=series.points.FirstOrDefault()?.mean??1;if(Math.Abs(baseValue)<1e-9)baseValue=1;foreach(var point in series.points)point.mean=point.mean/baseValue*100;}Rect r=GUILayoutUtility.GetRect(200,420,GUILayout.ExpandWidth(true));chart.Draw(r,normalized,"Player Level","Growth index");}
        }
        void DrawPlayerCurves(){if(playerSweep==null)return;var series=playerSweep.Curves(curveMetric);using(new EditorGUILayout.HorizontalScope()){if(GUILayout.Button("EXPORT SWEEP CSV"))status=WorkbenchExports.SaveSweepCsv(playerSweep,objective);if(GUILayout.Button("EXPORT CURVE PNG"))status=chart.ExportPng(series,"player_"+curveMetric);if(GUILayout.Button("EXPORT RESULT JSON"))status=WorkbenchExports.SaveJson("player_sweep",playerSweep);}Rect r=GUILayoutUtility.GetRect(200,440,GUILayout.ExpandWidth(true));chart.Draw(r,series,"Player Level",OptimizationMetricCatalog.Get(curveMetric).Name);Heading("CLICK-TO-INSPECT DATA");foreach(var p in playerSweep.points)if(GUILayout.Button($"L{p.playerLevel} / CL{p.combatLevel} / {p.profile}: {OptimizationMetricCatalog.Get(curveMetric).Value(p.metrics):0.###}")){playerBuild=p.build.Clone();playerMetrics=p.metrics;tab=Tab.PlayerBuildLab;}}
        void MetricPopup(){string[] names=OptimizationMetricCatalog.All.Select(x=>x.Name).ToArray();int i=Mathf.Max(0,OptimizationMetricCatalog.All.ToList().FindIndex(x=>x.Id==curveMetric));curveMetric=OptimizationMetricCatalog.All[EditorGUILayout.Popup("Curve Metric",i,names)].Id;}
        List<PlayerGearProfileSO> LoadProfiles()=>new[]{"Low","Mid","Optimized"}.Select(x=>AssetDatabase.LoadAssetAtPath<PlayerGearProfileSO>($"Assets/Balance/Profiles/SO_PlayerGearProfile_{x}.asset")).Where(x=>x!=null).ToList();
        void DrawTreeHeatmap(Rect rect)
        {
            double Value(PassiveMarginalResult x)=>heatmapMode switch{HeatmapMode.PrimaryMetric=>x.primaryDelta,HeatmapMode.SecondaryMetric=>x.secondaryDelta,HeatmapMode.PathAdjusted=>x.pathAdjustedValue,HeatmapMode.SelectedPath=>0,_=>x.objectiveDelta};
            var lookup=marginal.ToDictionary(x=>x.nodeId);double max=Math.Max(1e-9,marginal.Select(x=>Math.Abs(Value(x))).DefaultIfEmpty(0).Max());var chosen=new HashSet<string>(passiveResult?.build?.passiveStableIds??playerBuild.passiveStableIds??new());Vector2 center=rect.center+heatPan;
            Handles.BeginGUI();foreach(var e in PassiveTreeDefinition.Edges){Vector2 a=center+PassiveTreeDefinition.Node(e.A).LayoutPosition*heatZoom,b=center+PassiveTreeDefinition.Node(e.B).LayoutPosition*heatZoom;Handles.color=new Color(.25f,.28f,.34f,.45f);Handles.DrawLine(a,b);}Handles.EndGUI();
            foreach(var n in PassiveTreeDefinition.Nodes){Vector2 p=center+n.LayoutPosition*heatZoom;if(!rect.Contains(p))continue;Color c=new(.12f,.24f,.42f);string tip=n.DisplayName;if(lookup.TryGetValue(n.Id,out var v)){double value=Value(v);float t=(float)Math.Clamp(Math.Abs(value)/max,0,1);c=Color.Lerp(new Color(.2f,.45f,.75f),Color.Lerp(Color.yellow,Color.red,t),Mathf.Sqrt(t));tip+=$"\n{heatmapMode}: {value:+0.#####;-0.#####;0}\nPath {v.pathCost}";}if(chosen.Contains(n.StableId))c=Color.white;Rect nr=new(p.x-5,p.y-5,10,10);EditorGUI.DrawRect(nr,c);EditorGUI.LabelField(nr,new GUIContent("",tip));if(Event.current.type==EventType.MouseDown&&nr.Contains(Event.current.mousePosition)){lookup.TryGetValue(n.Id,out selectedMarginal);Event.current.Use();Repaint();}}
        }
        static void PingNode(int id){var n=PassiveTreeDefinition.Node(id);UnityEngine.Object asset=n.IsClassRoute?PassiveTreeDefinition.Database.ClassBranches.FirstOrDefault(x=>x.ClassId==n.RouteClassId):PassiveTreeDefinition.Database.WeaponBranches.FirstOrDefault(x=>x.WeaponId==n.RouteWeaponId);if(asset!=null){Selection.activeObject=asset;EditorGUIUtility.PingObject(asset);}}
        static void Compare(PlayerBuildMetrics a,PlayerBuildMetrics b){foreach(var m in OptimizationMetricCatalog.All){double av=m.Value(a),bv=m.Value(b),pct=Math.Abs(av)<1e-9?0:(bv-av)/Math.Abs(av);EditorGUILayout.LabelField(m.Name,$"A {av:0.###} · B {bv:0.###} · Δ {bv-av:+0.###;-0.###;0} ({pct:+0.##%;-0.##%;0%})");}}
    }
